"use client"

// Progressive arrival for sections, headings, media, lists. Wrap a region and it
// fades up as it enters the viewport; `stagger` lets its direct children take turns.
// The default mode is one-shot (data-in via IntersectionObserver, then the observer
// is gone); mode="scroll" is pure CSS and reversible. Reduced motion: inert.

import * as React from "react"
import "./reveal.css"

type Tag =
  | "div"
  | "section"
  | "article"
  | "header"
  | "ul"
  | "ol"
  | "figure"
  | "li"

export interface RevealProps extends React.HTMLAttributes<HTMLElement> {
  as?: Tag
  /** "once": arrive and stay (default). "scroll": tied to the scroll position. */
  mode?: "once" | "scroll"
  /** "up": fade + 16px rise (default). "fade": opacity only. */
  from?: "up" | "fade"
  /** Direct children arrive one after another, this many ms apart. Once mode only. */
  stagger?: number
  /** Fraction of the element that must be visible before it arrives. Default 0.2. */
  threshold?: number
}

export function Reveal({
  as = "div",
  mode = "once",
  from = "up",
  stagger,
  threshold = 0.2,
  className,
  style,
  children,
  ...rest
}: RevealProps) {
  const ref = React.useRef<HTMLElement>(null)
  React.useEffect(() => {
    if (mode !== "once") return
    const el = ref.current
    if (!el) return
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      el.dataset.in = ""
      return
    }
    const io = new IntersectionObserver(
      ([entry]) => {
        if (!entry?.isIntersecting) return
        el.dataset.in = ""
        io.disconnect()
      },
      // Tall elements may never reach a 20% ratio on a short viewport; a top-edge
      // root margin lets them arrive once their head is well inside.
      { threshold, rootMargin: "0px 0px -10% 0px" },
    )
    io.observe(el)
    return () => io.disconnect()
  }, [mode, threshold])
  return React.createElement(
    as,
    {
      ref,
      className: `ag-reveal${className ? ` ${className}` : ""}`,
      "data-mode": mode,
      "data-from": from,
      "data-stagger": stagger !== undefined ? "" : undefined,
      style:
        stagger !== undefined
          ? ({ "--stagger": `${stagger}ms`, ...style } as React.CSSProperties)
          : style,
      ...rest,
    },
    children,
  )
}

/* reveal: content that arrives as it enters the viewport, so no stretch of page is a
   scroll where nothing happens. Two modes. "once" (default): IntersectionObserver
   sets data-in, a transition plays, and that is that; scrolling back never hides it.
   "scroll": a CSS view() timeline, reversible, no JavaScript at all. Both are inert
   under prefers-reduced-motion, and the hidden start state only applies when a script
   can lift it (scripting: enabled), so content is never trapped invisible. */

.ag-reveal {
  --reveal-y: 16px;
  --stagger: 80ms;
}
.ag-reveal[data-from="fade"] {
  --reveal-y: 0px;
}

@keyframes ag-reveal {
  from {
    opacity: 0;
    transform: translateY(var(--reveal-y));
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: no-preference) and (scripting: enabled) {
  .ag-reveal[data-mode="once"]:not([data-stagger]) {
    opacity: 0;
    transform: translateY(var(--reveal-y));
    transition:
      opacity var(--dur-3, 500ms) var(--ease-out, ease-out),
      transform var(--dur-3, 500ms) var(--ease-out, ease-out);
  }
  .ag-reveal[data-mode="once"]:not([data-stagger])[data-in] {
    opacity: 1;
    transform: none;
  }

  /* Staggered: the wrapper stays put, its direct children take turns. */
  .ag-reveal[data-mode="once"][data-stagger] > * {
    opacity: 0;
    transform: translateY(var(--reveal-y));
    transition:
      opacity var(--dur-3, 500ms) var(--ease-out, ease-out),
      transform var(--dur-3, 500ms) var(--ease-out, ease-out);
    transition-delay: calc(var(--i, 0) * var(--stagger));
  }
  .ag-reveal[data-mode="once"][data-stagger][data-in] > * {
    opacity: 1;
    transform: none;
  }
  .ag-reveal[data-stagger] > :nth-child(1) {
    --i: 0;
  }
  .ag-reveal[data-stagger] > :nth-child(2) {
    --i: 1;
  }
  .ag-reveal[data-stagger] > :nth-child(3) {
    --i: 2;
  }
  .ag-reveal[data-stagger] > :nth-child(4) {
    --i: 3;
  }
  .ag-reveal[data-stagger] > :nth-child(5) {
    --i: 4;
  }
  .ag-reveal[data-stagger] > :nth-child(6) {
    --i: 5;
  }
  .ag-reveal[data-stagger] > :nth-child(7) {
    --i: 6;
  }
  .ag-reveal[data-stagger] > :nth-child(8) {
    --i: 7;
  }
  .ag-reveal[data-stagger] > :nth-child(9) {
    --i: 8;
  }
  .ag-reveal[data-stagger] > :nth-child(10) {
    --i: 9;
  }
  .ag-reveal[data-stagger] > :nth-child(11) {
    --i: 10;
  }
  .ag-reveal[data-stagger] > :nth-child(n + 12) {
    --i: 11;
  }
}

@media (prefers-reduced-motion: no-preference) {
  @supports (animation-timeline: view()) {
    .ag-reveal[data-mode="scroll"] {
      animation: ag-reveal linear both;
      animation-timeline: view();
      animation-range: entry 0% entry 40%;
    }
  }
}
